const simpson=(f,a,b,n=600)=>{const h=(b-a)/n;let s=f(a)+f(b);for(let i=1;i<n;i++)s+=f(a+i*h)*(i%2?4:2);return s*h/3};
/* mcq with a pool of distractors: drops duplicates and the answer itself, needs at least 3 left */
function M(q,ans,pool,why){ans=String(ans);const d=[];for(const x of pool){const s=String(x);if(s!==ans&&s!==""&&!d.includes(s))d.push(s)}if(d.length<3)throw new Error("gen_d: fewer than 3 distractors: "+q);return mcq(q,ans,d.slice(0,3),why)}
