function T(rows,f,b,w){const r=pick(rows),o=shuffle(rows.filter(x=>x!==r));if(!b||coin(.5))return M(f(r[0]),r[1],o.map(x=>x[1]),w(r));return M(b(r[1]),r[0],o.map(x=>x[0]),w(r))}
