const pl=(cs,v)=>{v=v||"x";const n=cs.length-1;let s="";cs.forEach((c,i)=>{const p=n-i;if(c===0)return;const a=Math.abs(c);const body=p===0?String(a):(a===1?"":String(a))+v+(p===1?"":"<sup>"+p+"</sup>");s+=s?(c<0?" − ":" + ")+body:(c<0?"−":"")+body});return s||"0"};
