   const k=pick([1,3]),ans=r2(((2**(k+1))-1)/(2*(k+1)));V(near3(simpson(x=>x*(1+x*x)**k,0,1),((2**(k+1))-1)/(2*(k+1))),"x(1+x²)^k");
