   if(v===0){const N0=pick([100,500,1000,5000]),td=pick([20,30,40]),n=rnd(2,6);return nat(`A culture starts with ${N0} cells and has a doubling time of ${td} min. How many cells are there after ${n*td} min of exponential growth?`,N0*Math.pow(2,n),`${n*td} min is ${n} generations, so N = ${N0} × 2<sup>${n}</sup> = ${N0*Math.pow(2,n)}.`)}
